package com.company.tpm.security; import com.vaadin.flow.spring.security.VaadinWebSecurity; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration @EnableMethodSecurity public class SecurityConfig extends VaadinWebSecurity { @Override protected void configure(HttpSecurity http)throws Exception{http.authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/telegram/webhook").permitAll());super.configure(http);setLoginView(http,"/login");} @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);} }
